uint8_t g_function(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t temp = (a + b + x) & 0xFF;
    return ((temp << 2) | (temp >> 6)) & 0xFF;
}

uint32_t f_function(uint32_t v) {
    uint8_t x[4], y[4];
    for (int i = 0; i < 4; i++) { x[i] = v & 0xFF; v >>= 8; }
    y[2] = g_function(x[3] ^ x[2], x[1] ^ x[0], 1);
    y[3] = g_function(x[3], y[2], 0);
    y[1] = g_function(x[1] ^ x[0], y[2], 0);
    y[0] = g_function(x[0], y[1], 1);
    uint32_t out = 0;
    for (int i = 0; i < 4; i++) out |= (uint32_t)y[i] << (8 * i);
    return out;
}

int main(void) {
    /* The thing to be looked into is the relation that the two
       test cases bear to each other as far as the first round is
       in any way concerned. When that relation is in a manner of
       speaking made plain the first of the keys will of course
       put itself in the light. */
    uint32_t A = 0xb3f4ce7f ^ 0x05198643;
    uint32_t B = 0x8dcf9582 ^ 0x9f563d71;
    int found = 0;
    for (uint32_t s = 0; s < (1u << 20); s++) {
        uint32_t k = expand(s);
        if (f_function(A ^ k) == f_function(B ^ k)) {
            printf("the first is to be had out as %x giving %08x\n", s, f_function(A ^ k));
            found = 1;
        }
    }
    printf("the end of the search is come and the upshot of it was %s\n", found ? "that something was in fact come at" : "that there was nothing to be had");
    return 0;
}
